const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const phoenix = ee.Geometry.Point([-112.0740, 33.4484]);
  const startDate = '2017-06-15';
  const endDate = '2017-06-22';

  // 2. Data Acquisition - MODIS Terra LST (day time)
  let lst = ee.ImageCollection('MODIS/006/MOD11A1')
    .filterDate(startDate, endDate)
    .filterBounds(phoenix)
    .select('LST_Day_1km');

  const imageCount = lst.size().getInfo();
  console.log(`Images found: ${imageCount}`);

  if (imageCount === 0) {
    console.log('No MODIS data available for this period.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing - Get maximum temperature
  const maxLst = lst.max();

  // Check valid pixels
  const pixelCount = maxLst.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: phoenix,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  console.log(`Valid pixels: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 4. Calculation - Get max temperature value
  const maxTempK = maxLst.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: phoenix,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  if (maxTempK === null || maxTempK === undefined) {
    console.log('Failed to retrieve temperature value.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Convert: MODIS LST is in Kelvin * 0.02
  const maxTempC = (maxTempK * 0.02) - 273.15;
  const maxTempF = (maxTempC * 9/5) + 32;

  console.log(`Max LST (raw): ${maxTempK}`);
  console.log(`Max temp: ${maxTempC.toFixed(2)}°C / ${maxTempF.toFixed(2)}°F`);

  // 5. Validation & Final Answer
  if (maxTempF > 150 || maxTempF < 50) {
    console.log('Temperature reading out of realistic range.');
    console.log('<answer>C3</answer>');
    return;
  }

  const threshold = 110.0;
  console.log(`Threshold: ${threshold}°F`);

  if (maxTempF >= threshold) {
    console.log(`Yes, temperature reached ${maxTempF.toFixed(2)}°F (>= 110°F)`);
    console.log('<answer>A</answer>');
  } else {
    console.log(`No, max temperature was ${maxTempF.toFixed(2)}°F (< 110°F)`);
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
